const body = $json.body || $json;
const title = body.title || body.name || 'New NeuroSpark article';
const url = body.url || `${$env.MARKETING_SITE_URL || 'https://neurospark.app'}/blog/${body.slug || ''}`;
const dek = body.dek || body.description || 'A practical brain-building read for parents.';
const utm = `${url}${url.includes('?') ? '&' : '?'}utm_source=content_distributor&utm_medium=social&utm_campaign=blog_distribution&ns_source=content_distributor`;
return [{ json: { title, url: utm, dek, body_md: body.body_md || '', tags: body.tags || [] } }];

const a = $('Normalize article payload').item.json;
const short = `${a.title}\n\n${a.dek}\n\nRead: ${a.url}`;
const posts = [
  { provider: 'linkedin', channelId: $env.POSTIZ_CHANNEL_LINKEDIN, content: short },
  { provider: 'x', channelId: $env.POSTIZ_CHANNEL_X, content: `${a.title}\n${a.url}` },
  { provider: 'threads', channelId: $env.POSTIZ_CHANNEL_THREADS, content: short },
  { provider: 'bluesky', channelId: $env.POSTIZ_CHANNEL_BLUESKY, content: `${a.title}\n${a.url}` },
  { provider: 'medium', channelId: $env.POSTIZ_CHANNEL_MEDIUM, content: a.body_md || short, settings: { __type: 'medium', title: a.title } },
  { provider: 'devto', channelId: $env.POSTIZ_CHANNEL_DEVTO, content: a.body_md || short, settings: { __type: 'devto', title: a.title, tags: (a.tags || []).slice(0,4) } }
].filter((p) => !!p.channelId);
return [{ json: { posts, tags: ['source:content_distributor'] } }];
